/**
 * The icons of the app. Builds made with an On Page token get the Font
 * Awesome Pro light icons of the design system, generated by
 * `scripts/pro-icons.mjs` into `icons/pro.generated.ts` (never in git: Pro
 * icons cannot be published); the others get the closest Font Awesome Free
 * icons (`icons/free.ts`). The build picks the set: `#icons` in
 * electron.vite.config.ts.
 */
export * from '#icons'
export type { IconDefinition } from '@fortawesome/fontawesome-svg-core'
